'use strict';

/** An error the user can fix: bad input, an unknown id, or an unreadable data file. */
class TodoError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = 'TodoError';
  }
}

function emptyState() {
  return { nextId: 1, todos: [] };
}

/**
 * Parses a command-line id. Only plain decimal digits are accepted, so "1.5",
 * "1e3", "-1" and " 1" are rejected rather than coerced by Number().
 */
function parseId(raw) {
  if (typeof raw !== 'string' || !/^\d+$/.test(raw)) {
    throw new TodoError(`Invalid id "${raw}". Expected a positive integer.`);
  }
  const id = Number(raw);
  if (id < 1 || !Number.isSafeInteger(id)) {
    throw new TodoError(`Invalid id "${raw}". Expected a positive integer.`);
  }
  return id;
}

/**
 * Returns a new state with the todo appended; the input state is not modified.
 * Whitespace runs (including newlines) collapse to one space so each todo
 * stays on a single line in `list` output.
 */
function addTodo(state, text, now = new Date()) {
  const normalized = typeof text === 'string' ? text.replace(/\s+/g, ' ').trim() : '';
  if (normalized === '') {
    throw new TodoError('Todo text cannot be empty.');
  }
  const todo = {
    id: state.nextId,
    text: normalized,
    completed: false,
    createdAt: now.toISOString(),
  };
  return {
    state: { ...state, nextId: state.nextId + 1, todos: [...state.todos, todo] },
    todo,
  };
}

function findIndex(state, id) {
  const index = state.todos.findIndex((todo) => todo.id === id);
  if (index === -1) {
    throw new TodoError(`Todo #${id} not found.`);
  }
  return index;
}

/**
 * Marks a todo as done. Completing an already-done todo is not an error;
 * `changed` is false in that case and the original state is returned.
 */
function completeTodo(state, id) {
  const index = findIndex(state, id);
  const existing = state.todos[index];
  if (existing.completed) {
    return { state, todo: existing, changed: false };
  }
  const todo = { ...existing, completed: true };
  const todos = state.todos.map((item, i) => (i === index ? todo : item));
  return { state: { ...state, todos }, todo, changed: true };
}

/** Removes a todo. `nextId` is left alone so a deleted id is never handed out again. */
function deleteTodo(state, id) {
  const index = findIndex(state, id);
  return {
    state: { ...state, todos: state.todos.filter((_, i) => i !== index) },
    todo: state.todos[index],
  };
}

function formatList(todos) {
  if (todos.length === 0) {
    return 'No todos yet.';
  }
  return todos.map((todo) => `${todo.id}. [${todo.completed ? 'x' : ' '}] ${todo.text}`).join('\n');
}

module.exports = {
  TodoError,
  emptyState,
  parseId,
  addTodo,
  completeTodo,
  deleteTodo,
  formatList,
};

