'use strict';

const fs = require('node:fs');
const { TodoError, emptyState } = require('./todos');

function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isPositiveInteger(value) {
  return Number.isSafeInteger(value) && value >= 1;
}

/** Returns a description of the first problem found, or null if the data is valid. */
function findProblem(data) {
  if (!isPlainObject(data)) {
    return 'expected an object with "nextId" and "todos"';
  }
  if (!isPositiveInteger(data.nextId)) {
    return '"nextId" must be a positive integer';
  }
  if (!Array.isArray(data.todos)) {
    return '"todos" must be an array';
  }
  const seen = new Set();
  for (const [i, todo] of data.todos.entries()) {
    const where = `todos[${i}]`;
    if (!isPlainObject(todo)) return `${where} must be an object`;
    if (!isPositiveInteger(todo.id)) return `${where}.id must be a positive integer`;
    if (seen.has(todo.id)) return `${where}.id ${todo.id} is a duplicate`;
    if (todo.id >= data.nextId) return `${where}.id ${todo.id} must be less than nextId ${data.nextId}`;
    if (typeof todo.text !== 'string') return `${where}.text must be a string`;
    if (typeof todo.completed !== 'boolean') return `${where}.completed must be a boolean`;
    if (typeof todo.createdAt !== 'string' || Number.isNaN(Date.parse(todo.createdAt))) {
      return `${where}.createdAt must be an ISO timestamp`;
    }
    seen.add(todo.id);
  }
  return null;
}

/**
 * Reads and validates the data file. A missing file is an empty list. Anything
 * unreadable or malformed throws a TodoError, so callers never overwrite a
 * file they could not understand.
 */
function loadState(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      return emptyState();
    }
    throw new TodoError(`Could not read ${filePath}: ${err.message}`, { cause: err });
  }

  let data;
  try {
    data = JSON.parse(raw);
  } catch (err) {
    throw new TodoError(
      `${filePath} is not valid JSON (${err.message}). Fix or remove the file and try again.`,
      { cause: err },
    );
  }

  const problem = findProblem(data);
  if (problem) {
    throw new TodoError(`${filePath} has invalid data: ${problem}. Fix or remove the file and try again.`);
  }
  return data;
}

/**
 * Writes to a temp file in the same directory and renames it into place, so an
 * interrupted write cannot leave a truncated data file behind.
 */
function saveState(filePath, state) {
  const tempPath = `${filePath}.${process.pid}.tmp`;
  try {
    fs.writeFileSync(tempPath, `${JSON.stringify(state, null, 2)}\n`);
    fs.renameSync(tempPath, filePath);
  } catch (err) {
    fs.rmSync(tempPath, { force: true });
    throw new TodoError(`Could not write ${filePath}: ${err.message}`, { cause: err });
  }
}

module.exports = { loadState, saveState };

