#!/usr/bin/env node
'use strict';

const path = require('node:path');
const {
  TodoError,
  parseId,
  addTodo,
  completeTodo,
  deleteTodo,
  formatList,
} = require('./src/todos');
const { loadState, saveState } = require('./src/store');

const DATA_FILE = 'todos.json';

const USAGE = `Usage:
  node index.js add "<text>"     Add a new todo
  node index.js list             List all todos
  node index.js complete <id>    Mark a todo as done
  node index.js delete <id>      Delete a todo`;

function requireIdArgument(command, args) {
  if (args.length === 0) {
    throw new TodoError(`Missing todo id. Usage: node index.js ${command} <id>`);
  }
  if (args.length > 1) {
    throw new TodoError(`Too many arguments. Usage: node index.js ${command} <id>`);
  }
  return parseId(args[0]);
}

/** Runs one command against the data file and returns the text to print. */
function run(args, filePath) {
  const [command, ...rest] = args;

  switch (command) {
    case 'add': {
      if (rest.length === 0) {
        throw new TodoError('Missing todo text. Usage: node index.js add "<text>"');
      }
      // Joining lets `add Buy groceries` work without quotes.
      const result = addTodo(loadState(filePath), rest.join(' '));
      saveState(filePath, result.state);
      return `Added todo #${result.todo.id}: ${result.todo.text}`;
    }
    case 'list': {
      if (rest.length > 0) {
        throw new TodoError('The list command takes no arguments. Usage: node index.js list');
      }
      return formatList(loadState(filePath).todos);
    }
    case 'complete': {
      const id = requireIdArgument(command, rest);
      const result = completeTodo(loadState(filePath), id);
      if (!result.changed) {
        return `Todo #${id} is already completed.`;
      }
      saveState(filePath, result.state);
      return `Completed todo #${id}: ${result.todo.text}`;
    }
    case 'delete': {
      const id = requireIdArgument(command, rest);
      const result = deleteTodo(loadState(filePath), id);
      saveState(filePath, result.state);
      return `Deleted todo #${id}: ${result.todo.text}`;
    }
    case 'help':
    case '--help':
    case '-h':
      return USAGE;
    case undefined:
      throw new TodoError(`No command given.\n${USAGE}`);
    default:
      throw new TodoError(`Unknown command "${command}".\n${USAGE}`);
  }
}

try {
  console.log(run(process.argv.slice(2), path.join(process.cwd(), DATA_FILE)));
} catch (err) {
  if (err instanceof TodoError) {
    console.error(`Error: ${err.message}`);
  } else {
    // Not a user error, so print the stack for the bug report.
    console.error(err);
  }
  process.exitCode = 1;
}

