'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const {
  TodoError,
  emptyState,
  parseId,
  addTodo,
  completeTodo,
  deleteTodo,
  formatList,
} = require('../src/todos');

const NOW = new Date('2026-01-02T03:04:05.000Z');

function stateWith(...todos) {
  const nextId = todos.reduce((max, todo) => Math.max(max, todo.id), 0) + 1;
  return { nextId, todos };
}

function todo(id, overrides = {}) {
  return { id, text: `Todo ${id}`, completed: false, createdAt: NOW.toISOString(), ...overrides };
}

describe('parseId', () => {
  for (const [raw, expected] of [
    ['1', 1],
    ['42', 42],
    ['007', 7],
    [String(Number.MAX_SAFE_INTEGER), Number.MAX_SAFE_INTEGER],
  ]) {
    it(`accepts "${raw}"`, () => {
      assert.equal(parseId(raw), expected);
    });
  }

  for (const raw of ['', 'abc', '0', '-1', '1.5', '1e3', '0x10', ' 1', '1 ', '١', '9007199254740993']) {
    it(`rejects ${JSON.stringify(raw)}`, () => {
      assert.throws(() => parseId(raw), { name: 'TodoError', message: /Invalid id/ });
    });
  }

  it('rejects a missing value', () => {
    assert.throws(() => parseId(undefined), TodoError);
  });
});

describe('addTodo', () => {
  it('creates a pending todo with the next id and an ISO timestamp', () => {
    const { state, todo } = addTodo(emptyState(), 'Buy groceries', NOW);
    assert.deepEqual(todo, {
      id: 1,
      text: 'Buy groceries',
      completed: false,
      createdAt: '2026-01-02T03:04:05.000Z',
    });
    assert.deepEqual(state, { nextId: 2, todos: [todo] });
  });

  it('assigns increasing ids across calls', () => {
    const first = addTodo(emptyState(), 'a', NOW);
    const second = addTodo(first.state, 'b', NOW);
    assert.deepEqual(second.state.todos.map((t) => t.id), [1, 2]);
    assert.equal(second.state.nextId, 3);
  });

  it('uses nextId rather than the highest existing id', () => {
    const state = { nextId: 10, todos: [todo(3)] };
    assert.equal(addTodo(state, 'x', NOW).todo.id, 10);
  });

  it('trims the text and collapses inner whitespace and newlines', () => {
    const { todo: added } = addTodo(emptyState(), '  Buy\n\tmilk   now  ', NOW);
    assert.equal(added.text, 'Buy milk now');
  });

  it('keeps unicode text intact', () => {
    const { todo: added } = addTodo(emptyState(), 'Café ☕ 買い物 👩‍💻', NOW);
    assert.equal(added.text, 'Café ☕ 買い物 👩‍💻');
  });

  for (const text of ['', '   ', '\n\t', undefined, null, 42]) {
    it(`rejects ${JSON.stringify(text) ?? 'undefined'} as text`, () => {
      assert.throws(() => addTodo(emptyState(), text, NOW), {
        name: 'TodoError',
        message: 'Todo text cannot be empty.',
      });
    });
  }

  it('does not modify the input state', () => {
    const state = stateWith(todo(1));
    const snapshot = structuredClone(state);
    addTodo(state, 'new', NOW);
    assert.deepEqual(state, snapshot);
  });
});

describe('completeTodo', () => {
  it('marks a pending todo as completed', () => {
    const result = completeTodo(stateWith(todo(1), todo(2)), 2);
    assert.equal(result.changed, true);
    assert.equal(result.todo.completed, true);
    assert.deepEqual(result.state.todos.map((t) => t.completed), [false, true]);
  });

  it('reports no change for a todo that is already completed', () => {
    const state = stateWith(todo(1, { completed: true }));
    const result = completeTodo(state, 1);
    assert.equal(result.changed, false);
    assert.equal(result.state, state);
  });

  it('throws for an id that does not exist', () => {
    assert.throws(() => completeTodo(stateWith(todo(1)), 5), {
      name: 'TodoError',
      message: 'Todo #5 not found.',
    });
  });

  it('throws on an empty list', () => {
    assert.throws(() => completeTodo(emptyState(), 1), TodoError);
  });

  it('does not modify the input state', () => {
    const state = stateWith(todo(1));
    const snapshot = structuredClone(state);
    completeTodo(state, 1);
    assert.deepEqual(state, snapshot);
  });
});

describe('deleteTodo', () => {
  it('removes only the matching todo and returns it', () => {
    const result = deleteTodo(stateWith(todo(1), todo(2), todo(3)), 2);
    assert.equal(result.todo.id, 2);
    assert.deepEqual(result.state.todos.map((t) => t.id), [1, 3]);
  });

  it('keeps nextId so a deleted id is not reused', () => {
    const afterDelete = deleteTodo(stateWith(todo(1), todo(2)), 2).state;
    assert.equal(afterDelete.nextId, 3);
    assert.equal(addTodo(afterDelete, 'new', NOW).todo.id, 3);
  });

  it('throws for an id that does not exist', () => {
    assert.throws(() => deleteTodo(stateWith(todo(1)), 2), {
      name: 'TodoError',
      message: 'Todo #2 not found.',
    });
  });

  it('does not modify the input state', () => {
    const state = stateWith(todo(1), todo(2));
    const snapshot = structuredClone(state);
    deleteTodo(state, 1);
    assert.deepEqual(state, snapshot);
  });
});

describe('formatList', () => {
  it('prints a message when there are no todos', () => {
    assert.equal(formatList([]), 'No todos yet.');
  });

  it('prints id, status indicator and text on one line per todo', () => {
    const output = formatList([todo(1, { text: 'Buy groceries' }), todo(4, { text: 'Walk dog', completed: true })]);
    assert.equal(output, '1. [ ] Buy groceries\n4. [x] Walk dog');
  });
});

