const { describe, it, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { loadState, saveState } = require('../src/store');

const VALID_TODO = { id: 1, text: 'Buy groceries', completed: false, createdAt: '2026-01-02T03:04:05.000Z' };

let dir;
let file;

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-store-'));
  file = path.join(dir, 'todos.json');
});

afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});

describe('loadState', () => {
  it('returns an empty state when the file does not exist', () => {
    assert.deepEqual(loadState(file), { nextId: 1, todos: [] });
    assert.equal(fs.existsSync(file), false);
  });

  it('returns the saved state', () => {
    const state = { nextId: 2, todos: [VALID_TODO] };
    fs.writeFileSync(file, JSON.stringify(state));
    assert.deepEqual(loadState(file), state);
  });

  for (const [label, content] of [
    ['an empty file', ''],
    ['truncated JSON', '{"nextId": 2, "todos": ['],
    ['plain text', 'not json'],
  ]) {
    it(`rejects ${label} and names the file`, () => {
      fs.writeFileSync(file, content);
      assert.throws(() => loadState(file), {
        name: 'TodoError',
        message: new RegExp(`^${escapeRegExp(file)} is not valid JSON`),
      });
    });
  }

  for (const [label, data, problem] of [
    ['an array', [VALID_TODO], 'expected an object'],
    ['null', null, 'expected an object'],
    ['a missing nextId', { todos: [] }, '"nextId" must be a positive integer'],
    ['a zero nextId', { nextId: 0, todos: [] }, '"nextId" must be a positive integer'],
    ['a string nextId', { nextId: '2', todos: [] }, '"nextId" must be a positive integer'],
    ['todos that are not an array', { nextId: 1, todos: {} }, '"todos" must be an array'],
    ['a todo that is not an object', { nextId: 2, todos: ['x'] }, 'todos[0] must be an object'],
    ['a fractional id', { nextId: 3, todos: [{ ...VALID_TODO, id: 1.5 }] }, 'todos[0].id must be a positive integer'],
    ['a duplicate id', { nextId: 2, todos: [VALID_TODO, VALID_TODO] }, 'todos[1].id 1 is a duplicate'],
    ['an id at or above nextId', { nextId: 1, todos: [VALID_TODO] }, 'todos[0].id 1 must be less than nextId 1'],
    ['a missing text', { nextId: 2, todos: [{ ...VALID_TODO, text: undefined }] }, 'todos[0].text must be a string'],
    ['a string completed flag', { nextId: 2, todos: [{ ...VALID_TODO, completed: 'no' }] }, 'todos[0].completed must be a boolean'],
    ['an unparseable createdAt', { nextId: 2, todos: [{ ...VALID_TODO, createdAt: 'yesterday' }] }, 'todos[0].createdAt must be an ISO timestamp'],
  ]) {
    it(`rejects ${label}`, () => {
      fs.writeFileSync(file, JSON.stringify(data));
      assert.throws(() => loadState(file), {
        name: 'TodoError',
        message: new RegExp(`has invalid data: ${escapeRegExp(problem)}`),
      });
    });
  }

  it('reports a read error other than a missing file', () => {
    fs.mkdirSync(file);
    assert.throws(() => loadState(file), { name: 'TodoError', message: /^Could not read/ });
  });
});

describe('saveState', () => {
  it('writes state that loadState reads back, including unicode', () => {
    const state = { nextId: 2, todos: [{ ...VALID_TODO, text: 'Café ☕ 買い物 👩‍💻' }] };
    saveState(file, state);
    assert.deepEqual(loadState(file), state);
  });

  it('replaces an existing file and leaves no temp file behind', () => {
    saveState(file, { nextId: 1, todos: [] });
    saveState(file, { nextId: 2, todos: [VALID_TODO] });
    assert.deepEqual(loadState(file).todos, [VALID_TODO]);
    assert.deepEqual(fs.readdirSync(dir), ['todos.json']);
  });

  it('reports a failed write and removes the temp file', () => {
    // A non-empty directory at the target path makes the final rename fail.
    fs.mkdirSync(file);
    fs.writeFileSync(path.join(file, 'keep'), '');
    assert.throws(() => saveState(file, { nextId: 1, todos: [] }), {
      name: 'TodoError',
      message: /^Could not write/,
    });
    assert.deepEqual(fs.readdirSync(dir), ['todos.json']);
  });
});

function escapeRegExp(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

