  if (result.error) throw result.error;
  return { code: result.status, stdout: result.stdout, stderr: result.stderr };
}

function readData() {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function assertFails(result, message) {
  assert.equal(result.code, 1, `expected exit code 1, got ${result.code}: ${result.stdout}`);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, message);
}

describe('add', () => {
  it('saves a pending todo to todos.json in the current directory', () => {
    const result = cli('add', 'Buy groceries');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Added todo #1: Buy groceries\n');

    const data = readData();
    assert.equal(data.nextId, 2);
    assert.equal(data.todos.length, 1);
    const [saved] = data.todos;
    assert.equal(saved.id, 1);
    assert.equal(saved.text, 'Buy groceries');
    assert.equal(saved.completed, false);
    assert.equal(new Date(saved.createdAt).toISOString(), saved.createdAt);
  });

  it('assigns auto-incrementing ids', () => {
    cli('add', 'first');
    cli('add', 'second');
    assert.equal(cli('add', 'third').stdout, 'Added todo #3: third\n');
    assert.deepEqual(readData().todos.map((t) => t.id), [1, 2, 3]);
  });

  it('joins unquoted words into one todo', () => {
    assert.equal(cli('add', 'Walk', 'the', 'dog').stdout, 'Added todo #1: Walk the dog\n');
  });

  it('stores unicode text unchanged', () => {
    cli('add', 'Café ☕ 買い物 👩‍💻');
    assert.equal(readData().todos[0].text, 'Café ☕ 買い物 👩‍💻');
    assert.equal(cli('list').stdout, '1. [ ] Café ☕ 買い物 👩‍💻\n');
  });

  it('fails without text and does not create the file', () => {
    assertFails(cli('add'), /Missing todo text/);
    assert.equal(fs.existsSync(file), false);
  });

  it('fails on whitespace-only text', () => {
    assertFails(cli('add', '   '), /Todo text cannot be empty/);
    assert.equal(fs.existsSync(file), false);
  });
});

describe('list', () => {
  it('reports an empty list when no file exists, without creating one', () => {
    const result = cli('list');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'No todos yet.\n');
    assert.equal(fs.existsSync(file), false);
  });

  it('reports an empty list after every todo is deleted', () => {
    cli('add', 'only');
    cli('delete', '1');
    assert.equal(cli('list').stdout, 'No todos yet.\n');
  });

  it('shows id, status indicator and text for each todo', () => {
    cli('add', 'Buy groceries');
    cli('add', 'Walk the dog');
    cli('complete', '2');
    const result = cli('list');
    assert.equal(result.code, 0);
